export interface Row { id: number; name: string; tags: string[] }

export function transform0(rows: Row[], limit = 10): Row[] {
  const seen = new Set<number>()
  const result: Row[] = []
  for (const row of rows) {
    if (seen.has(row.id) || result.length >= limit) continue
    seen.add(row.id)
    result.push({ ...row, tags: row.tags.filter((tag) => tag.length > 0) })
  }
  return result
}

